<span class="line"><span style="color:#A6ACCD;">mv </span><span style="color:#89DDFF;">/</span><span style="color:#A6ACCD;">opt</span><span style="color:#89DDFF;">/</span><span style="color:#A6ACCD;">lamp </span><span style="color:#89DDFF;">/</span><span style="color:#A6ACCD;">etc</span><span style="color:#89DDFF;">/</span><span style="color:#A6ACCD;">udev  </span><span style="color:#676E95;font-style:italic;">// 将opt目录下的lamp移至 /etc/udev 目录下</span></span>
